{
  "missing_information": [
    {
      "category": "Trigger",
      "gap": "It is unclear what initiates the pickup arrangement process each day — whether it is a fixed daily schedule, a calendar event, a reminder, or an ad-hoc decision.",
      "why_it_matters": "The trigger determines whether the workflow can be automated proactively or must remain reactive, and affects when any notifications or checks should fire."
    },
    {
      "category": "Caregiver Pool",
      "gap": "There is no information about how many potential pickup persons exist, how they are identified, or how the selection among them is made.",
      "why_it_matters": "Understanding the pool size and selection logic is essential to model the decision step and assess whether it can be automated or requires manual input."
    },
    {
      "category": "Communication Channel",
      "gap": "The method used to notify or confirm with the pickup person is not described (e.g., phone call, text message, app, email).",
      "why_it_matters": "The channel determines integration points for automation and affects how confirmation of receipt can be captured programmatically."
    },
    {
      "category": "Change Handling",
      "gap": "The process for handling a mid-day change of pickup person is not defined — who initiates it, how the original person is informed, and how the school or care facility is notified.",
      "why_it_matters": "Change scenarios are a key exception path; without this detail the workflow cannot be fully modelled and exception-handling automation cannot be designed."
    },
    {
      "category": "Arrival Confirmation",
      "gap": "It is not specified how the parent verifies that the child arrived home safely — whether this is a message from the caregiver, a check-in app, a phone call, or something else.",
      "why_it_matters": "The confirmation mechanism defines the closing event of the workflow and determines whether automated status tracking or alerts for non-arrival can be implemented."
    },
    {
      "category": "Escalation / No-Show",
      "gap": "There is no description of what happens if the pickup person does not collect the child or if no arrival confirmation is received within an expected time window.",
      "why_it_matters": "Without an escalation path, the workflow has no defined end state for failure cases, making it impossible to model completeness or automate safety alerts."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What causes you to start arranging the pickup on any given day — for example, is it a fixed daily routine, a reminder you set, or does something specific prompt you to begin?",
      "targets": ["Trigger"]
    },
    {
      "id": "Q2",
      "question": "When you decide who will collect your child, how do you choose among the available people — is there a priority order, a shared schedule, or do you decide case by case each day?",
      "targets": ["Caregiver Pool"]
    },
    {
      "id": "Q3",
      "question": "What channel do you use to contact the pickup person to confirm they will collect your child, and do they send you any acknowledgement back?",
      "targets": ["Communication Channel"]
    },
    {
      "id": "Q4",
      "question": "When the pickup person changes during the day, can you walk me through exactly what steps you take — including who you inform and in what order?",
      "targets": ["Change Handling"]
    },
    {
      "id": "Q5",
      "question": "How do you confirm that your child has arrived home safely — what does that look like in practice, and who sends or triggers that confirmation?",
      "targets": ["Arrival Confirmation"]
    },
    {
      "id": "Q6",
      "question": "If you do not receive confirmation that your child has been collected or has arrived home by a certain time, what do you do next?",
      "targets": ["Escalation / No-Show"]
    }
  ]
}
